	VPCMPEQB  (DX)(R12*1), Y0, Y0
	VMOVDQU   32(R10)(R12*1), Y1
	VPCMPEQB  32(DX)(R12*1), Y1, Y1
	VMOVDQU   64(R10)(R12*1), Y2
	VPCMPEQB  64(DX)(R12*1), Y2, Y2
	VMOVDQU   96(R10)(R12*1), Y3
	VPCMPEQB  96(DX)(R12*1), Y3, Y3
	VPAND     Y1, Y0, Y0
	VPAND     Y3, Y2, Y2
	VPAND     Y2, Y0, Y0
	VPMOVMSKB Y0, R11
	CMPL      R11, $-1
	JNE       wide_done_repeat_extend_encodeBlockPrefix512K
	ADDL      $0x00000080, R12
	SUBL      $0x00000080, CX
	CMPL      CX, $0x00000080
	JAE       wide_loop_repeat_extend_encodeBlockPrefix512K

wide_done_repeat_extend_encodeBlockPrefix512K:
	VZEROUPPER

wide_skip_repeat_extend_encodeBlockPrefix512K:
	JMP matchlen_loop_16_entry_repeat_extend_encodeBlockPrefix512K
	PCALIGN $0x10

matchlen_loopback_16_repeat_extend_encodeBlockPrefix512K:
	MOVQ (R10)(R12*1), R11
	MOVQ 8(R10)(R12*1), R13
	XORQ (DX)(R12*1), R11
	JNZ  matchlen_bsf_8_repeat_extend_encodeBlockPrefix512K
	XORQ 8(DX)(R12*1), R13
	JNZ  matchlen_bsf_16repeat_extend_encodeBlockPrefix512K
	LEAL -16(CX), CX
	LEAL 16(R12), R12

matchlen_loop_16_entry_repeat_extend_encodeBlockPrefix512K:
	CMPL CX, $0x10
	JAE  matchlen_loopback_16_repeat_extend_encodeBlockPrefix512K
	JMP  matchlen_match8_repeat_extend_encodeBlockPrefix512K
	PCALIGN $0x10

matchlen_bsf_16repeat_extend_encodeBlockPrefix512K:
	TZCNTQ R13, R13
	SARQ   $0x03, R13
	LEAL   8(R12)(R13*1), R12
	JMP    repeat_extend_forward_end_encodeBlockPrefix512K

matchlen_match8_repeat_extend_encodeBlockPrefix512K:
	CMPL CX, $0x08
	JB   matchlen_match4_repeat_extend_encodeBlockPrefix512K
	MOVQ (R10)(R12*1), R11
	XORQ (DX)(R12*1), R11
	JNZ  matchlen_bsf_8_repeat_extend_encodeBlockPrefix512K
	LEAL -8(CX), CX
	LEAL 8(R12), R12
	JMP  matchlen_match4_repeat_extend_encodeBlockPrefix512K
	PCALIGN $0x10

matchlen_bsf_8_repeat_extend_encodeBlockPrefix512K:
	TZCNTQ R11, R11
	SARQ   $0x03, R11
	ADDL   R11, R12
	JMP    repeat_extend_forward_end_encodeBlockPrefix512K

matchlen_match4_repeat_extend_encodeBlockPrefix512K:
	CMPL CX, $0x04
	JB   matchlen_match2_repeat_extend_encodeBlockPrefix512K
	MOVL (R10)(R12*1), R11
	CMPL (DX)(R12*1), R11
	JNE  matchlen_match2_repeat_extend_encodeBlockPrefix512K
	LEAL -4(CX), CX
	LEAL 4(R12), R12

matchlen_match2_repeat_extend_encodeBlockPrefix512K:
	CMPL CX, $0x01
	JE   matchlen_match1_repeat_extend_encodeBlockPrefix512K
	JB   repeat_extend_forward_end_encodeBlockPrefix512K
	MOVW (R10)(R12*1), R11
	CMPW (DX)(R12*1), R11
	JNE  matchlen_match1_repeat_extend_encodeBlockPrefix512K
	LEAL 2(R12), R12
	SUBL $0x02, CX
	JZ   repeat_extend_forward_end_encodeBlockPrefix512K

matchlen_match1_repeat_extend_encodeBlockPrefix512K:
	MOVB (R10)(R12*1), R11
	CMPB (DX)(R12*1), R11
	JNE  repeat_extend_forward_end_encodeBlockPrefix512K
	LEAL 1(R12), R12
	JMP  repeat_extend_forward_end_encodeBlockPrefix512K

wide_sse_repeat_extend_encodeBlockPrefix512K:
sse_loop_repeat_extend_encodeBlockPrefix512K:
	MOVOU    (R10)(R12*1), X0
	MOVOU    (DX)(R12*1), X1
	PCMPEQB  X1, X0
	MOVOU    16(R10)(R12*1), X1
	MOVOU    16(DX)(R12*1), X2
	PCMPEQB  X2, X1
	MOVOU    32(R10)(R12*1), X2
	MOVOU    32(DX)(R12*1), X3
	PCMPEQB  X3, X2
	MOVOU    48(R10)(R12*1), X3
	MOVOU    48(DX)(R12*1), X4
	PCMPEQB  X4, X3
	MOVOU    64(R10)(R12*1), X4
	MOVOU    64(DX)(R12*1), X5
	PCMPEQB  X5, X4
	MOVOU    80(R10)(R12*1), X5
	MOVOU    80(DX)(R12*1), X6
	PCMPEQB  X6, X5
	MOVOU    96(R10)(R12*1), X6
	MOVOU    96(DX)(R12*1), X7
	PCMPEQB  X7, X6
	MOVOU    112(R10)(R12*1), X7
	MOVOU    112(DX)(R12*1), X8
	PCMPEQB  X8, X7
	PAND     X1, X0
	PAND     X3, X2
	PAND     X5, X4
	PAND     X7, X6
	PAND     X2, X0
	PAND     X6, X4
	PAND     X4, X0
	PMOVMSKB X0, R11
	CMPL     R11, $0x0000ffff
	JNE      wide_skip_repeat_extend_encodeBlockPrefix512K
	ADDL     $0x00000080, R12
	SUBL     $0x00000080, CX
	CMPL     CX, $0x00000080
	JAE      sse_loop_repeat_extend_encodeBlockPrefix512K
	JMP      wide_skip_repeat_extend_encodeBlockPrefix512K
	PCALIGN $0x10

repeat_extend_forward_end_encodeBlockPrefix512K:
	ADDL R12, DI
	MOVL DI, CX
	SUBL R9, CX
	MOVQ 16(SP), DX

	// emitRepeat
	CMPL CX, $0x1d
	JBE  repeat_one_match_repeat_encodeBlockPrefix512K
	LEAL -30(CX), DX
	CMPL CX, $0x0000011e
	JB   repeat_two_match_repeat_encodeBlockPrefix512K
